class transaction extends uvm_sequence_item;
`uvm_object_utils(transaction)
logic[941-1:0] inputs;
logic[972-1:0] data;
int sample_id;
function new(string name="transaction"); super.new(name); endfunction
endclass
class stimulus_sequence extends uvm_sequence#(transaction);
`uvm_object_utils(stimulus_sequence)
function new(string name="stimulus_sequence"); super.new(name); endfunction
task emit(input logic[941-1:0] value);
transaction item;
item=transaction::type_id::create("item"); start_item(item); item.inputs=value; finish_item(item);
endtask
