if(actual_value[7 +: 1]===1'b1 && expected_value[7 +: 1]===1'b1) begin
mask[48 +: 8]='1;
mask[152 +: 32]='1;
mask[18 +: 2]='1;
mask[23 +: 1]='1;
mask[11 +: 1]='1;
end
return (actual_value & mask)===(expected_value & mask) && !$isunknown({actual_value & mask,expected_value & mask});
endfunction
function void compare(int identity);
if(actual_pending.exists(identity) && predicted_pending.exists(identity)) begin
checked++;
if(!equal_outputs(actual_pending[identity].data,predicted_pending[identity].data))
`uvm_error("COMPARE",$sformatf("sample=%0d inputs=%h actual=%h expected=%h",identity,actual_pending[identity].inputs,actual_pending[identity].data,predicted_pending[identity].data))
actual_pending.delete(identity); predicted_pending.delete(identity);
end
endfunction
function void write_actual(transaction item); actual_pending[item.sample_id]=item; compare(item.sample_id); endfunction
function void write_predicted(transaction item); predicted_pending[item.sample_id]=item; compare(item.sample_id); endfunction
endclass
class protocol_checker_component extends uvm_subscriber#(transaction);
`uvm_component_utils(protocol_checker_component)
function new(string name,uvm_component parent); super.new(name,parent); endfunction
function void write(transaction item);
if($isunknown(item.data[232 +: 4]) || !$onehot0(item.data[232 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[236 +: 4]) || !$onehot0(item.data[236 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[0 +: 4]) || !$onehot0(item.data[0 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[184 +: 4]) || !$onehot0(item.data[184 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[4 +: 4]) || !$onehot0(item.data[4 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[404 +: 4]) || !$onehot0(item.data[404 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[688 +: 4]) || !$onehot0(item.data[688 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[240 +: 4]) || !$onehot0(item.data[240 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[400 +: 4]) || !$onehot0(item.data[400 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
if($isunknown(item.data[396 +: 4]) || !$onehot0(item.data[396 +: 4])) `uvm_error("PROTOCOL","unknown or multiply routed channel control")
endfunction
endclass
