class environment extends uvm_env;
`uvm_component_utils(environment)
uvm_sequencer#(transaction) sequencer;
driver drv; monitor mon; predictor pred; scoreboard sb; protocol_checker_component protocol_checker; coverage cov;
function new(string name,uvm_component parent); super.new(name,parent); endfunction
function void build_phase(uvm_phase phase);
sequencer=uvm_sequencer#(transaction)::type_id::create("sequencer",this);
drv=driver::type_id::create("drv",this); mon=monitor::type_id::create("mon",this); pred=predictor::type_id::create("pred",this);
sb=scoreboard::type_id::create("sb",this); protocol_checker=protocol_checker_component::type_id::create("protocol_checker",this); cov=coverage::type_id::create("cov",this);
endfunction
function void connect_phase(uvm_phase phase);
drv.seq_item_port.connect(sequencer.seq_item_export); mon.observed.connect(sb.actual_export); pred.expected.connect(sb.predicted_export);
mon.observed.connect(protocol_checker.analysis_export); mon.observed.connect(cov.analysis_export);
endfunction
endclass
class dvbench_test extends uvm_test;
`uvm_component_utils(dvbench_test)
environment env;
virtual native_if vif;
function new(string name="dvbench_test",uvm_component parent=null); super.new(name,parent); endfunction
function void build_phase(uvm_phase phase);
env=environment::type_id::create("env",this);
if(!uvm_config_db#(virtual native_if)::get(this,"","vif",vif)) `uvm_fatal("CFG","missing native interface")
endfunction
task run_phase(uvm_phase phase);
stimulus_sequence sequence_instance;
phase.raise_objection(this); sequence_instance=stimulus_sequence::type_id::create("sequence_instance"); sequence_instance.start(env.sequencer);
repeat(5) @(negedge vif.clk); phase.drop_objection(this);
endtask
function void report_phase(uvm_phase phase);
if(env.sb.checked<10807 || env.sb.actual_pending.num()!=0 || env.sb.predicted_pending.num()!=0) `uvm_error("NONVACUITY","insufficient checks or unpaired observations")
if(uvm_report_server::get_server().get_severity_count(UVM_ERROR)==0 && uvm_report_server::get_server().get_severity_count(UVM_FATAL)==0)
`uvm_info("DVBench_COMPLETED","DVBench_COMPLETED",UVM_NONE)
endfunction
endclass
endpackage
